/*
 * dump/sau2/dump.s - the DUMP page (SAU2): the crash-dump code and its cells
 *
 * Generated by: Claude Opus 5.5
 *
 * Bead source-gfn1 (step 2 of epic source-nqcs).  The SAU2 map gives the
 * page a load region of its own, and calls it a data segment:
 *
 *   D23  E00400  DUMP               loaded at 101C00, size = 400
 *   D    E00400  DUMP               size = 400
 *        E00400  DUMP
 *        E00762  DUMP_$SMAP_PHADDR
 *        E007E8  DUMP_$RARS_PHADDR
 *        E007EC  DUMP_$ADDRS
 *
 * The page is file 0x800..0xC00 of the image (low 0x101C00).  COLD_START
 * copies it to physical 0x100C00 (PPN 0x403, cold/sau2/cold_start.s
 * 0x10154E) and maps it at VA 0xE00400.  Nothing in the kernel jumps to
 * it (no longword 0xE00400 / 0xE00404 in the image): it is entered from
 * the boot PROM after a crash, by physical address, with the MMU in any
 * state.  It is position-independent apart from six absolute operands,
 * which the binder listed in RELOC (docs/rfc-cold-start.md section 5 step
 * 8: the six DUMP cells) and which are symbol references here:
 * CRASH_$RECORD + 0x100 (its stack, in the CRASH_RECORD page),
 * CRASH_REPORT + 0x10 (the crash status, misc/crash_system.h), MMU, and
 * PTT / PTT + 0x100000 (the absolute map symbols of
 * arch/m68k/sau2/iodefs.s).  Every other constant is physical (the PFT and
 * PTT entries of the dump page itself, the MMU control register at 0x8000
 * before the MMU is on, the kernel's first physical page 0x102000) or a
 * PROM vector, as in the image.
 *
 * What it does, as far as the bytes show:
 *   - DUMP (0xE00400) enters with d7 = 1, dump_start_2 (0xE00404) with
 *     d7 = 2; A5 = DUMP, SP = CRASH_$RECORD + 0x100, A6 = SP.
 *   - On the first entry (bit 0 of dump_flags clear) it maps itself: PTT
 *     slot for its own physical page = PPN 0x403, PFT entries 0x403/0x3,
 *     with the old PTT/PFT words saved in the frame; on a 68020 the masks
 *     differ (bit 1 of dump_flags).
 *   - PROM vector 0x10C fills the frame's first three words (the device
 *     type in (A6)); type 2 or 6 is a network dump: the crash status
 *     goes into the packet, a request (op 0) is sent and the server's
 *     name printed.
 *   - It then sends every 1 KB page of the DUMP_$ADDRS ranges (op 2,
 *     dump_send_page), a `!' every 32 pages, stopping after 0x4D0 pages
 *     on a type-1 device; then the page tables (PTT, PFT, the MMU
 *     registers) as 35 more pages built at physical 0x102000; then, on a
 *     network dump unless the server said op 4, a final request; prints
 *     "Done" and returns to the PROM through vector 0x11C.
 *   - dump_xfer sends through PROM vector 0x120 (10 tries, "Xbad") and,
 *     on a network dump, waits for a reply through vector 0x110 (3 tries,
 *     "Rbad"), checking the peer id, the reply type and sequence ("Bad
 *     rpy", "Nm sad - St=<status>").
 * The PROM vectors 0x10C, 0x110 and 0x120 are not named anywhere in the
 * tree; 0x108 is the PROM's putc (dtty/sau2/prom_io.s) and 0x11C
 * PROM_$QUIET_RET_ADDR (misc/crash_system.h).
 *
 * The five routines Ghidra had found in the kernel program (FUN_00e005bc,
 * FUN_00e005c6, FUN_00e006cc, FUN_00e006d2, FUN_00e006dc) are named from
 * their behaviour: dump_send_page, dump_send_request, dump_puts_nl,
 * dump_puts, dump_put_hex_nl; with dump_putc (0xE006F8) and the shared
 * body dump_xfer (0xE005CE).  They are module-local labels: register
 * arguments, not C-callable.
 *
 * Encodings are the image's; the <ea>=#imm forms of AND/CMP/ADD (cabc,
 * b03c, b23c, d23c) are `.short' opcode words, as in
 * misc/sau2/disp_lites.s.  One section, .text.DUMP: the code reaches its
 * cells through A5 = DUMP with fixed displacements and through (d16,PC).
 */

        .section ".text.DUMP","ax",@progbits
        .balign 4

        .globl  DUMP
        .globl  DUMP_$SMAP_PHADDR
        .globl  DUMP_$RARS_PHADDR
        .globl  DUMP_$ADDRS

        .set    DUMP_STACK_TOP, CRASH_$RECORD + 0x100 /* 0xE00100, in the CRASH_RECORD page */
        .set    CRASH_STATUS,   CRASH_REPORT + 0x10   /* 0xE1E98E, crash_report_t.status */

        .equ    PROM_MACHINE_ID_LO, 0x00000103  /* low byte of PROM_$MACHINE_ID (0x100); bit 1 = 68020 */
        .equ    PROM_VEC_PUTC,  0x00000108  /* PROM putc vector (d1 = the char) */
        .equ    PROM_VEC_10C,   0x0000010C  /* PROM vector: the dump device (3 var args) */
        .equ    PROM_VEC_110,   0x00000110  /* PROM vector: receive (4 var args) */
        .equ    PROM_VEC_QUIET, 0x0000011C  /* PROM_$QUIET_RET_ADDR: back to the PROM */
        .equ    PROM_VEC_120,   0x00000120  /* PROM vector: send (4 var args) */
        .equ    PROM_CELL_100,  0x00000100  /* PROM_$MACHINE_ID */
        .equ    MMU_CSR_PHYS,   0x00008000  /* the MMU control register, physical */
        .equ    MMU_CSR_PHYS_2, 0x00008002  /* the word after it */
        .equ    PFT_PHYS,       0x00004000  /* the page frame table, physical */
        .equ    PFT_PHYS_END,   0x00008000
        .equ    PFT_DUMP,       0x0000400C  /* PFT[3]: the PFT entry of PPN 3 */
        .equ    PFT_DUMP_PAGE,  0x0000500C  /* PFT[0x403]: the dump page's own entry */
        .equ    PFT_DUMP_PAGE_HI, 0x00005010
        .equ    DUMP_PHYS,      0x00100C00  /* PPN 0x403 */
        .equ    KERNEL_PHYS,    0x00102000  /* PPN 0x408: the kernel's first page, scratch here */
        .equ    DUMP_RCV_BUF,   0x00100124  /* physical: the receive buffer (VA 0xE00124) */

        .equ    DUMP_OFF_PKT_LEN,  0x31C    /* 0xE0071C dump_pkt_len */
        .equ    DUMP_OFF_PKT_OP,   0x32F    /* 0xE0072F dump_pkt_op */
        .equ    DUMP_OFF_PKT_SEQ,  0x330    /* 0xE00730 dump_pkt_seq */
        .equ    DUMP_OFF_FLAGS,    0x360    /* 0xE00760 dump_flags */

DUMP:
        moveq   #1,%d7                  /* e00400 */
        bra.s   dump_common             /* e00402 */
dump_start_2:
        moveq   #2,%d7                  /* e00404 */
dump_common:
        lea     (DUMP:w,%pc),%a5        /* e00406  A5 = DUMP */
        lea     DUMP_STACK_TOP,%sp      /* e0040a  a RELOC cell */
        movea.l %sp,%fp                 /* e00410  the frame */
        move.l  #0x400,%d6              /* e00412  the page size */
        bset    #0,(DUMP_OFF_FLAGS,%a5) /* e00418  entered before? */
        bne.s   dump_mmu_on             /* e0041e */
        move.w  #2,MMU_CSR_PHYS         /* e00420  CSR = 2 (PTT access) */
        move.l  #0x01711003,%d4         /* e00428  PFT entry for PPN 0x403 */
        move.l  #0x000fff00,%d5         /* e0042e  PTT index mask */
        btst    #1,(PROM_MACHINE_ID_LO).w /* e00434 */
        beq.s   dump_map_self           /* e0043a */
        bset    #1,(DUMP_OFF_FLAGS,%a5) /* e0043c  68020 */
        bclr    #16,%d4                 /* e00442 */
        lsl.l   #2,%d5                  /* e00446 */
dump_map_self:
        .short  0xcabc                  /* e00448  and.l #DUMP_PHYS,%d5 (<ea>=#imm form) */
        .long   DUMP_PHYS
        movea.l #PTT,%a4                /* e0044e  a RELOC cell */
        move.w  (0,%a4,%d5.l),%d0       /* e00454  save the PTT slot, */
        move.l  (PFT_DUMP_PAGE).w,%d1   /* e00458      PFT[0x403] */
        move.l  (PFT_DUMP).w,%d2        /* e0045c      and PFT[3] */
        move.w  #0x403,(0,%a4,%d5.l)    /* e00460 */
        move.l  %d4,(PFT_DUMP_PAGE).w   /* e00466 */
        move.l  #0x00709403,(PFT_DUMP).w /* e0046a */
        move.w  #0x160,(PFT_DUMP_PAGE_HI).w /* e00472 */
        move.w  #1,MMU_CSR_PHYS         /* e00478  the MMU on */
        movem.l %d0-%d3/%d5,(0xc,%fp)   /* e00480  the saved words */
        bra.s   dump_mmu_done           /* e00486 */
dump_mmu_on:
        move.w  #1,MMU_CSR_PHYS         /* e00488 */
dump_mmu_done:
        move.b  #0xff,(0).w             /* e00490 */
        move.w  %d7,(%fp)               /* e00496  entry 1 or 2 */
        clr.w   (2,%fp)                 /* e00498 */
        pea     (4,%fp)                 /* e0049c */
        pea     (2,%fp)                 /* e004a0 */
        pea     (%fp)                   /* e004a4 */
        movea.l (PROM_VEC_10C).w,%a0    /* e004a6 */
        jsr     (%a0)                   /* e004aa */
        adda.w  #0xc,%sp                /* e004ac */
        cmpi.w  #2,(%fp)                /* e004b0  device 2 or 6: a network dump */
        beq.s   dump_net_open           /* e004b4 */
        cmpi.w  #6,(%fp)                /* e004b6 */
        bne.s   dump_ranges             /* e004ba */
dump_net_open:
        move.l  CRASH_STATUS,(DUMP_OFF_PKT_SEQ,%a5) /* e004bc  a RELOC cell */
        moveq   #0,%d0                  /* e004c4  op 0 */
        bsr.w   dump_send_request       /* e004c6 */
        movea.l (0x20,%fp),%a1          /* e004ca  the reply */
        lea     (0xc,%a1),%a0           /* e004ce */
        bsr.w   dump_puts               /* e004d2  the server's name */
dump_ranges:
        move.l  #0x23,(DUMP_OFF_PKT_SEQ,%a5) /* e004d6 */
        moveq   #31,%d5                 /* e004de  a `!' every 32 pages */
        lea     (DUMP_$ADDRS:w,%pc),%a3 /* e004e0 */
dump_range_loop:
        move.l  (%a3)+,%d7              /* e004e4  start (0 ends) */
        beq.s   dump_tables             /* e004e6 */
        move.l  (%a3)+,%d4              /* e004e8  end */
dump_page_loop:
        bsr.w   dump_send_page          /* e004ea */
        addq.l  #1,(DUMP_OFF_PKT_SEQ,%a5) /* e004ee */
        cmpi.w  #1,(%fp)                /* e004f2 */
        bne.s   dump_page_tick          /* e004f6 */
        cmpi.l  #0x4d0,(DUMP_OFF_PKT_SEQ,%a5) /* e004f8  device 1: at most 0x4D0 */
        bge.s   dump_tables             /* e00500 */
dump_page_tick:
        dbf     %d5,dump_page_next      /* e00502 */
        move.b  #0x21,%d1               /* e00506  `!' */
        bsr.w   dump_putc               /* e0050a */
        moveq   #31,%d5                 /* e0050e */
dump_page_next:
        add.l   %d6,%d7                 /* e00510 */
        cmp.l   %d7,%d4                 /* e00512 */
        bge.s   dump_page_loop          /* e00514 */
        bra.s   dump_range_loop         /* e00516 */

/*
 * 0xE00518: the page tables as 35 pages built at physical 0x102000: the
 * PTT (one word per 1 KB of the window), the PFT, the saved PFT/PTT words
 * of the dump page and the MMU registers.
 */
dump_tables:
        lea     KERNEL_PHYS,%a4         /* e00518  49f9 abs.l */
        move.l  %a4,%d7                 /* e0051e */
        movem.l (0xc,%fp),%d0-%d3/%d5   /* e00520 */
        move.w  #0,MMU                  /* e00526  a RELOC cell */
        lea     (0x200,%a4),%a4         /* e0052e */
        move.l  (PROM_CELL_100).w,(-0x1fe,%a4) /* e00532 */
        move.w  #2,MMU_CSR_PHYS         /* e00538 */
        lea     PTT,%a3                 /* e00540  a RELOC cell */
        movea.l %a4,%a2                 /* e00546 */
dump_copy_ptt:
        move.w  (%a3),(%a4)+            /* e00548 */
        adda.w  %d6,%a3                 /* e0054a */
        cmpa.l  #PTT + 0x100000,%a3     /* e0054c  a RELOC cell (0x800000) */
        bne.s   dump_copy_ptt           /* e00552 */
        lsr.l   #8,%d5                  /* e00554 */
        lsr.l   #1,%d5                  /* e00556 */
        move.w  %d0,(0,%a2,%d5.w)       /* e00558  the dump page's saved PTT word */
        lea     (PFT_PHYS).w,%a3        /* e0055c */
dump_copy_pft:
        move.w  (%a3)+,(%a4)+           /* e00560 */
        cmpa.l  #PFT_PHYS_END,%a3       /* e00562 */
        bne.s   dump_copy_pft           /* e00568 */
        move.l  %d1,(-0x2ff4,%a4)       /* e0056a  saved PFT[0x403] */
        move.l  %d2,(-0x3ff4,%a4)       /* e0056e  saved PFT[3] */
        movea.l %a2,%a4                 /* e00572 */
        adda.l  #0x8800,%a4             /* e00574 */
        clr.l   (%a4)+                  /* e0057a */
        move.w  MMU_CSR_PHYS_2,(%a4)+   /* e0057c  38f9 abs.l */
        move.w  #1,MMU_CSR_PHYS         /* e00582 */
        clr.l   (DUMP_OFF_PKT_SEQ,%a5)  /* e0058a */
        moveq   #34,%d5                 /* e0058e  35 pages */
dump_tables_loop:
        bsr.w   dump_send_page          /* e00590 */
        addq.l  #1,(DUMP_OFF_PKT_SEQ,%a5) /* e00594 */
        add.l   %d6,%d7                 /* e00598 */
        dbf     %d5,dump_tables_loop    /* e0059a */
dump_finish:
        cmpi.w  #1,(%fp)                /* e0059e */
        beq.s   dump_done               /* e005a2 */
        moveq   #4,%d0                  /* e005a4  op 4 */
        cmp.b   (dump_pkt_op:w,%pc),%d0 /* e005a6 */
        beq.s   dump_done               /* e005aa */
        bsr.s   dump_send_request       /* e005ac */
dump_done:
        lea     (dump_str_done:w,%pc),%a0 /* e005ae */
        bsr.w   dump_puts_nl            /* e005b2 */
        movea.l (PROM_VEC_QUIET).w,%a0  /* e005b6 */
        jmp     (%a0)                   /* e005ba */

/*
 * dump_send_page, 0xE005BC (FUN_00e005bc): send the page at d7 (op 2,
 * length d6).  dump_send_request, 0xE005C6 (FUN_00e005c6): send op d0
 * with length 0 (the page number is that of DUMP itself, d7 = A5).  Both
 * save d0-d7/a1-a4 and share dump_xfer.
 */
dump_send_page:
        movem.l %d0-%d7/%a1-%a4,-(%sp)  /* e005bc */
        moveq   #2,%d0                  /* e005c0 */
        move.l  %d6,%d1                 /* e005c2 */
        bra.s   dump_xfer               /* e005c4 */
dump_send_request:
        movem.l %d0-%d7/%a1-%a4,-(%sp)  /* e005c6 */
        clr.w   %d1                     /* e005ca */
        move.l  %a5,%d7                 /* e005cc */
dump_xfer:
        move.w  %d1,(DUMP_OFF_PKT_LEN,%a5) /* e005ce */
        move.b  %d0,(DUMP_OFF_PKT_OP,%a5)  /* e005d2 */
        move.l  %d7,%d0                 /* e005d6  the page number */
        lsr.l   #8,%d0                  /* e005d8 */
        lsr.l   #2,%d0                  /* e005da */
        move.w  %d0,(0xa,%fp)           /* e005dc */
        move.w  #10,(8,%fp)             /* e005e0  10 tries */
dump_xfer_send:
        pea     (4,%fp)                 /* e005e6  status */
        pea     (dump_peer_id:w,%pc)    /* e005ea */
        pea     (0xa,%fp)               /* e005ee */
        pea     (dump_pkt_seq:w,%pc)    /* e005f2 */
        movea.l (PROM_VEC_120).w,%a0    /* e005f6 */
        jsr     (%a0)                   /* e005fa */
        adda.w  #0x10,%sp               /* e005fc */
        move.l  (4,%fp),%d0             /* e00600 */
        beq.s   dump_xfer_sent          /* e00604 */
        subq.w  #1,(8,%fp)              /* e00606 */
        bne.s   dump_xfer_send          /* e0060a */
        lea     (dump_str_xbad:w,%pc),%a0 /* e0060c */
        bra.w   dump_xfer_fail          /* e00610 */
dump_xfer_return:
        movem.l (%sp)+,%d0-%d7/%a1-%a4  /* e00614 */
        rts                             /* e00618 */
dump_xfer_sent:
        cmpi.w  #1,(%fp)                /* e0061a  device 1: no reply */
        beq.s   dump_xfer_return        /* e0061e */
dump_xfer_receive:
        move.w  #3,(8,%fp)              /* e00620  3 tries */
dump_xfer_receive_try:
        pea     (4,%fp)                 /* e00626  status */
        move.l  #DUMP_RCV_BUF,-(%sp)    /* e0062a */
        pea     (dump_rcv_len:w,%pc)    /* e00630 */
        pea     (dump_pkt_seq:w,%pc)    /* e00634 */
        movea.l (PROM_VEC_110).w,%a0    /* e00638 */
        jsr     (%a0)                   /* e0063c */
        adda.w  #0x10,%sp               /* e0063e */
        move.l  (4,%fp),%d0             /* e00642 */
        beq.s   dump_xfer_reply         /* e00646 */
        subq.w  #1,(8,%fp)              /* e00648 */
        bne.s   dump_xfer_send          /* e0064c */
        lea     (dump_str_rbad:w,%pc),%a0 /* e0064e */
        bra.s   dump_xfer_fail          /* e00652 */
dump_xfer_reply:
        lea     (0x24,%fp),%a0          /* e00654  the reply header */
        move.l  (dump_peer_id:w,%pc),%d0 /* e00658 */
        cmp.l   (8,%a0),%d0             /* e0065c  from our peer? */
        bne.s   dump_xfer_receive       /* e00660 */
        lea     (0x1e,%a0),%a1          /* e00662 */
        clr.l   %d0                     /* e00666 */
        move.b  (0x18,%a0),%d0          /* e00668 */
        adda.l  %d0,%a1                 /* e0066c  the reply body */
        move.l  %a1,(0x20,%fp)          /* e0066e */
        cmpi.w  #2,(%a1)                /* e00672 */
        bne.s   dump_xfer_bad_type      /* e00676 */
        cmpi.w  #1,(2,%a1)              /* e00678 */
        bne.s   dump_xfer_bad_type      /* e0067e */
        move.b  (5,%a1),%d0             /* e00680 */
        subq.l  #1,%d0                  /* e00684 */
        cmp.b   (dump_pkt_op:w,%pc),%d0 /* e00686  the reply to our op? */
        beq.s   dump_xfer_check_seq     /* e0068a */
dump_xfer_bad_type:
        cmpi.b  #7,(5,%a1)              /* e0068c */
        bne.s   dump_xfer_bad_reply     /* e00692 */
dump_xfer_retry:
        bra.s   dump_xfer_receive       /* e00694 */
dump_xfer_bad_reply:
        lea     (dump_str_bad_rpy:w,%pc),%a0 /* e00696 */
        bsr.s   dump_puts               /* e0069a */
dump_xfer_abort:
        bra.w   dump_finish             /* e0069c */
dump_xfer_check_seq:
        .short  0xb03c, 0x0002          /* e006a0  cmp.b #2,%d0 (<ea>=#imm form) */
        bne.s   dump_xfer_check_status  /* e006a4 */
        move.l  (dump_pkt_seq:w,%pc),%d0 /* e006a6 */
        cmp.l   (0xc,%a1),%d0           /* e006aa */
        bne.s   dump_xfer_retry         /* e006ae */
dump_xfer_check_status:
        move.l  (6,%a1),%d0             /* e006b0  the server's status */
        beq.w   dump_xfer_return        /* e006b4 */
        lea     (dump_str_nm_sad:w,%pc),%a0 /* e006b8 */
dump_xfer_fail:
        move.l  %d0,-(%sp)              /* e006bc  "<msg> - St=<status>" */
        bsr.s   dump_puts               /* e006be */
        lea     (dump_str_st:w,%pc),%a0 /* e006c0 */
        bsr.s   dump_puts               /* e006c4 */
        move.l  (%sp)+,%d0              /* e006c6 */
        bsr.s   dump_put_hex_nl         /* e006c8 */
        bra.s   dump_xfer_abort         /* e006ca */

/* dump_puts_nl, 0xE006CC (FUN_00e006cc): print the string at a0, then CR LF. */
dump_puts_nl:
        bsr.s   dump_puts               /* e006cc */
dump_put_nl:
        lea     (dump_str_nl:w,%pc),%a0 /* e006ce */
/* dump_puts, 0xE006D2 (FUN_00e006d2): print the NUL-terminated string at a0. */
dump_puts:
        move.b  (%a0)+,%d1              /* e006d2 */
        beq.s   dump_rts                /* e006d4 */
        bsr.s   dump_putc               /* e006d6 */
        bra.s   dump_puts               /* e006d8 */
        rts                             /* e006da  (unreachable, as in the image) */

/* dump_put_hex_nl, 0xE006DC (FUN_00e006dc): print d0 as 8 hex digits, then CR LF. */
dump_put_hex_nl:
        moveq   #7,%d2                  /* e006dc */
dump_put_hex_digit:
        rol.l   #4,%d0                  /* e006de */
        moveq   #15,%d1                 /* e006e0 */
        and.b   %d0,%d1                 /* e006e2 */
        .short  0xb23c, 0x000a          /* e006e4  cmp.b #10,%d1 (<ea>=#imm form) */
        blt.s   dump_put_hex_ascii      /* e006e8 */
        addq.b  #7,%d1                  /* e006ea  'A' - '0' - 10 */
dump_put_hex_ascii:
        .short  0xd23c, 0x0030          /* e006ec  add.b #'0',%d1 (<ea>=#imm form) */
        bsr.s   dump_putc               /* e006f0 */
        dbf     %d2,dump_put_hex_digit  /* e006f2 */
        bra.s   dump_put_nl             /* e006f6 */

/* dump_putc, 0xE006F8: the character in d1 through the PROM, every register kept. */
dump_putc:
        movem.l %d0-%d7/%a0-%a4,-(%sp)  /* e006f8 */
        movea.l (PROM_VEC_PUTC).w,%a0   /* e006fc */
        jsr     (%a0)                   /* e00700 */
        movem.l (%sp)+,%d0-%d7/%a0-%a4  /* e00702 */
dump_rts:
        rts                             /* e00706 */

/*
 * 0xE00708: the cells.  The packet the PROM send/receive vectors take
 * (dump_pkt_seq is its first argument) with its length word and op byte
 * just ahead of it; the peer id the reply must carry; the receive length;
 * the messages; the flags; and the map's three public cells.
 */
dump_peer_id:
        .long   0                       /* e00708 */
        .long   0, 0                    /* e0070c */
        .byte   0x01, 0x01, 0x00, 0x00  /* e00714 */
        .byte   0x00, 0x2c, 0x00, 0x0a  /* e00718 */
dump_pkt_len:
        .short  0x0000                  /* e0071c */
